import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().go();
    }

    void go() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] poly = new int[10];
        for (int i = 0; i < k; i++) {
            poly[in.nextInt()] = 1;
        }
        int[] ans = new int[]{1};
        int exp = n / 2;
        while (true) {
            if ((exp & 1) == 1) {
                ans = multiply(ans, poly, MOD);
            }
            exp >>>= 1;
            if (exp == 0) break;
            poly = multiply(poly, poly, MOD);
        }
        long sum = 0;
        for (int val : ans) {
            sum = (sum + (long)val * val) % MOD;
        }
        out.println(sum);
        out.close();
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int len = a.length + b.length - 1;
        int size = 1;
        while (size < len) size <<= 1;

        double[] ar = new double[size];
        double[] ai = new double[size];
        for (int i = 0; i < a.length; i++) {
            long x = ((long)a[i] % mod + mod) % mod;
            ar[i] = x & 0x7FFF;
            ai[i] = x >>> 15;
        }

        fft(ar, ai, false);

        double[] br = new double[size];
        double[] bi = new double[size];
        if (a == b) {
            System.arraycopy(ar, 0, br, 0, size);
            System.arraycopy(ai, 0, bi, 0, size);
        } else {
            for (int i = 0; i < b.length; i++) {
                long x = ((long)b[i] % mod + mod) % mod;
                br[i] = x & 0x7FFF;
                bi[i] = x >>> 15;
            }
            fft(br, bi, false);
        }

        double[] resR = new double[size];
        double[] resI = new double[size];
        double scale = 0.25 / size;

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = ar[i] + ar[j];
            double a1i = ai[i] - ai[j];
            double a2r = ai[i] + ai[j];
            double a2i = ar[j] - ar[i];

            double b1r = br[i] + br[j];
            double b1i = bi[i] - bi[j];
            double b2r = bi[i] + bi[j];
            double b2i = br[j] - br[i];

            resR[i] = (a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r) * scale;
            resI[i] = (a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i) * scale;
        }

        fft(resR, resI, true);

        int[] result = new int[len];
        for (int i = 0; i < len; i++) {
            long real = Math.round(resR[i]);
            long imag = Math.round(resI[i]);
            long low = real % mod;
            long high = imag % mod;
            result[i] = (int)((low + (high << 15)) % mod);
        }
        return result;
    }

    void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >>> 1;
            for (; (j & bit) != 0; bit >>>= 1) j ^= bit;
            j ^= bit;
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int step = 2; step <= n; step <<= 1) {
            int half = step >>> 1;
            double[] cos = new double[half];
            double[] sin = new double[half];
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / step * (inverse ? -1 : 1);
                cos[i] = Math.cos(angle);
                sin[i] = Math.sin(angle);
            }

            for (int i = 0; i < n; i += step) {
                for (int k = 0; k < half; k++) {
                    double cr = re[i + k + half] * cos[k] - im[i + k + half] * sin[k];
                    double ci = re[i + k + half] * sin[k] + im[i + k + half] * cos[k];

                    double ur = re[i + k];
                    double ui = im[i + k];

                    re[i + k] = ur + cr;
                    im[i + k] = ui + ci;
                    re[i + k + half] = ur - cr;
                    im[i + k + half] = ui - ci;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int idx, len;

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int next() {
            if (len == -1) throw new InputMismatchException();
            if (idx >= len) {
                idx = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new InputMismatchException(); }
                if (len <= 0) return -1;
            }
            return buf[idx++] & 255;
        }

        public int nextInt() {
            int c = next();
            while (c <= 32) c = next();
            int s = 1;
            if (c == '-') { s = -1; c = next(); }
            int r = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                r = r * 10 + c - '0';
                c = next();
            }
            return r * s;
        }
    }
}
